// frontend/src/App.js
import React, { useEffect, useState } from 'react';
import './App.css';

function App() {
  // --- State for Mining Calculator ---
  const [hashrate, setHashrate] = useState('50');              // TH/s
  const [powerConsumption, setPowerConsumption] = useState('3000'); // Watts
  const [electricityCost, setElectricityCost] = useState('0.12');   // $/kWh
  const [networkDifficulty, setNetworkDifficulty] = useState('30000000000000'); // Example difficulty
  const [bitcoinPrice, setBitcoinPrice] = useState('');         // Fetched from API

  const [results, setResults] = useState(null);

  // --- Fetch real-time Bitcoin price (optional) ---
  useEffect(() => {
    const fetchBtcPrice = async () => {
      try {
        const response = await fetch(
          'https://api.coingecko.com/api/v3/simple/price?ids=bitcoin&vs_currencies=usd'
        );
        const data = await response.json();
        if (data.bitcoin && data.bitcoin.usd) {
          setBitcoinPrice(data.bitcoin.usd.toString());
        } else {
          setBitcoinPrice('27000'); // fallback default
        }
      } catch (error) {
        console.error('Error fetching BTC price:', error);
        setBitcoinPrice('27000');
      }
    };

    fetchBtcPrice();
  }, []);

  // --- Bitcoin Mining Calculation Formula ---
  const handleSubmit = (e) => {
    e.preventDefault();

    const hashrateNum = parseFloat(hashrate);          // in TH/s
    const powerNum = parseFloat(powerConsumption);       // in Watts
    const elecCostNum = parseFloat(electricityCost);       // $/kWh
    const btcPriceNum = parseFloat(bitcoinPrice) || 0;    // fallback if not fetched
    const difficultyNum = parseFloat(networkDifficulty);

    // Convert TH/s to H/s (1 TH/s = 1e12 H/s)
    const hashrateHs = hashrateNum * 1e12;

    // Constants for Bitcoin mining
    const blockReward = 6.25;             // BTC per block
    const blocksPerDay = 144;             // Approx. blocks mined per day
    const twoPow32 = 4294967296;          // 2^32

    // Calculate daily BTC mined
    const dailyBTC = (hashrateHs / (difficultyNum * twoPow32)) * blockReward * blocksPerDay;

    // Daily revenue in USD
    const dailyRevenue = dailyBTC * btcPriceNum;

    // Electricity cost: convert Watts to kW, multiply by 24 hours
    const dailyElecCost = (powerNum / 1000) * 24 * elecCostNum;

    // Estimated profits
    const dailyProfit = dailyRevenue - dailyElecCost;
    const monthlyProfit = dailyProfit * 30;
    const yearlyProfit = dailyProfit * 365;

    setResults({
      dailyProfit,
      monthlyProfit,
      yearlyProfit,
      dailyBTC,
      dailyRevenue,
      dailyElecCost
    });
  };

  return (
    <div className="app">
      {/* HEADER */}
      <header className="header">
        <h1>Bitcoin Mining Profitability Calculator</h1>
        <p>
          Estimate your daily, monthly, and yearly profits using real-time Bitcoin price data and your mining rig's parameters.
        </p>
      </header>

      {/* CALCULATOR SECTION */}
      <main className="calc-layout">
        {/* Left Column: Input Form */}
        <section className="card left-col">
          <h2>Enter Mining Parameters</h2>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label htmlFor="hashrate">Hashrate (TH/s):</label>
              <input
                id="hashrate"
                type="number"
                placeholder="e.g., 50"
                value={hashrate}
                onChange={(e) => setHashrate(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="powerConsumption">Power Consumption (Watts):</label>
              <input
                id="powerConsumption"
                type="number"
                placeholder="e.g., 3000"
                value={powerConsumption}
                onChange={(e) => setPowerConsumption(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="electricityCost">Electricity Cost ($/kWh):</label>
              <input
                id="electricityCost"
                type="number"
                placeholder="e.g., 0.12"
                step="0.01"
                value={electricityCost}
                onChange={(e) => setElectricityCost(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="bitcoinPrice">Bitcoin Price ($):</label>
              <input
                id="bitcoinPrice"
                type="number"
                value={bitcoinPrice}
                onChange={(e) => setBitcoinPrice(e.target.value)}
                required
              />
            </div>
            <div className="form-group">
              <label htmlFor="networkDifficulty">Network Difficulty:</label>
              <input
                id="networkDifficulty"
                type="number"
                placeholder="e.g., 30000000000000"
                value={networkDifficulty}
                onChange={(e) => setNetworkDifficulty(e.target.value)}
                required
              />
            </div>
            <button type="submit" className="calculate-btn">Calculate</button>
          </form>
        </section>

        {/* Right Column: Results */}
        <section className="card right-col">
          <h2>Results</h2>
          {results ? (
            <div className="results">
              <div className="result-row">
                <span>Daily Profit:</span>
                <strong>${results.dailyProfit.toFixed(2)}</strong>
              </div>
              <div className="result-row">
                <span>Monthly Profit:</span>
                <strong>${results.monthlyProfit.toFixed(2)}</strong>
              </div>
              <div className="result-row">
                <span>Yearly Profit:</span>
                <strong>${results.yearlyProfit.toFixed(2)}</strong>
              </div>
              <hr />
              <div className="result-row">
                <span>Daily BTC Mined:</span>
                <strong>{results.dailyBTC.toFixed(8)} BTC</strong>
              </div>
              <div className="result-row">
                <span>Daily Revenue:</span>
                <strong>${results.dailyRevenue.toFixed(2)}</strong>
              </div>
              <div className="result-row">
                <span>Daily Electricity Cost:</span>
                <strong>${results.dailyElecCost.toFixed(2)}</strong>
              </div>
            </div>
          ) : (
            <p>Enter your mining parameters to see estimated profits.</p>
          )}
        </section>
      </main>

      {/* INFORMATIONAL SECTION */}
      <section className="info-section">
        <div className="info-container">
          <h2>Types of GICs</h2>
          <ul>
            <li><strong>Non-redeemable GICs:</strong> Offer the highest interest rates but require keeping your money invested until maturity.</li>
            <li><strong>Redeemable GICs:</strong> Provide flexibility to withdraw early, typically with lower rates.</li>
            <li><strong>Market-linked GICs:</strong> Combine guaranteed principal with returns tied to market performance.</li>
            <li><strong>Cashable GICs:</strong> Allow withdrawal without penalty after a minimum holding period.</li>
          </ul>

          <h2>Factors Influencing GIC Rates</h2>
          <ul>
            <li>The Bank of Canada's policy rate directly impacts GIC returns. Track current rates on the Bank of Canada website.</li>
            <li>Longer investment terms typically offer higher interest rates.</li>
            <li>Financial institutions may offer better rates for larger deposits.</li>
            <li>Competition between banks and credit unions can lead to rate variations.</li>
          </ul>

          <h2>Investment Protection</h2>
          <ul>
            <li>GICs from eligible financial institutions are protected by CDIC insurance up to $100,000.</li>
            <li>Principal is guaranteed, making GICs a secure investment option.</li>
            <li>Interest rates are locked in for the term, providing predictable returns.</li>
          </ul>

          <h2>Frequently Asked Questions</h2>
          <ul>
            <li>What is a GIC?</li>
            <li>How is the interest calculated?</li>
            <li>What are the common GIC terms?</li>
            <li>Are GICs a safe investment?</li>
            <li>What is the minimum investment for a GIC?</li>
          </ul>

          <h2>About</h2>
          <p>
            GICCalculator.ca provides Canadians with free tools to calculate and compare GIC returns.
          </p>

          <h2>Quick Links</h2>
          <ul>
            <li>Calculator</li>
            <li>Blog</li>
            <li>About Us</li>
            <li>Contact</li>
            <li>Legal</li>
            <li>Privacy Policy</li>
            <li>Terms of Service</li>
          </ul>

          <p className="disclaimer">
            Disclaimer: This calculator provides estimates only. Please consult with your financial institution for actual rates and returns.
          </p>
          <p className="copyright">
            © 2025 GICCalculator.ca. All rights reserved.
          </p>
        </div>
      </section>

      {/* FOOTER */}
      <footer className="footer">
        <p>&copy; {new Date().getFullYear()} Bitcoin Mining Calculator</p>
      </footer>
    </div>
  );
}

export default App;
